// Package hypertext serves the issue tracker's pages. Its routes are
// generated by muxt from pages.gohtml; the forms inside the pages are
// rendered by jsonhandler from the schemas in package schemas.
package hypertext

import (
	"context"
	"database/sql"
	"encoding/json/jsontext"
	"encoding/json/v2"
	"errors"
	"fmt"
	"html/template"
	"log/slog"
	"net/http"
	"net/url"
	"strconv"

	"github.com/crhntr/jsonschema/jsonhandler"

	"github.com/crhntr/jsonschema/examples/issues/internal/database"
	"github.com/crhntr/jsonschema/examples/issues/internal/model"
	"github.com/crhntr/jsonschema/examples/issues/schemas"
)

//go:generate go tool muxt generate --use-receiver-type=Server --output-htmx

// Server is the routes receiver.
type Server struct {
	db  *sql.DB
	q   *database.Queries
	log *slog.Logger

	issueForm, contactForm, settingsForm *jsonhandler.Handler
}

// New returns a Server storing its data in db, which must already have
// its tables (see database.Migrate).
func New(ctx context.Context, db *sql.DB, log *slog.Logger) (*Server, error) {
	s := &Server{db: db, q: database.New(db), log: log}
	for _, f := range []struct {
		handler **jsonhandler.Handler
		schema  []byte
		id      string
		submit  string
	}{
		{&s.issueForm, schemas.Issue(), "issue", "Save issue"},
		{&s.contactForm, schemas.Contact(), "contact", "Save contact"},
		{&s.settingsForm, schemas.Settings(), "settings", "Save settings"},
	} {
		h, err := jsonhandler.New(ctx, f.schema)
		if err != nil {
			return nil, fmt.Errorf("%s form: %w", f.id, err)
		}
		h.ID, h.SubmitLabel = f.id, f.submit
		*f.handler = h
	}
	return s, nil
}

// Routes registers the pages and the form stylesheet.
func Routes(mux *http.ServeMux, s *Server) TemplateRoutePaths {
	paths := TemplateRoutes(mux, s)
	mux.HandleFunc("GET /jsonform.css", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
		_, _ = w.Write(jsonhandler.Stylesheet())
	})
	return paths
}

// Layout is what every page's frame shows.
type Layout struct {
	Project string
	Section string
}

func (s *Server) layout(ctx context.Context, section string) (Layout, error) {
	settings, err := s.settings(ctx)
	return Layout{Project: settings.Project, Section: section}, err
}

// settings returns the saved settings, or the schema's defaults.
func (s *Server) settings(ctx context.Context) (model.Settings, error) {
	row, err := s.q.GetSettings(ctx)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return model.Settings{Project: "My project"}, nil
	case err != nil:
		return model.Settings{}, s.publish(err)
	}
	var settings model.Settings
	if err := json.Unmarshal([]byte(row.Body), &settings); err != nil {
		return model.Settings{}, s.publish(fmt.Errorf("decode settings: %w", err))
	}
	return settings, nil
}

// FormPage is a page that is mostly a form.
type FormPage struct {
	Layout
	Title string
	Form  template.HTML
}

// FormResponse is the answer to a post of a form: the form again (after
// an edit, or with errors), or where to go after a successful save.
type FormResponse struct {
	FormPage
	Location string
	status   int
}

// StatusCode is 422 for a form with errors, otherwise 200.
func (r FormResponse) StatusCode() int {
	if r.status == 0 {
		return http.StatusOK
	}
	return r.status
}

// formSpec ties a form to a record: the handler and value to edit, where
// the form posts, and how a valid submission is saved.
type formSpec struct {
	title    string
	handler  *jsonhandler.Handler
	value    jsontext.Value
	action   string
	validate string
	section  string
	// save stores a valid value and returns the page to go to next.
	save func(ctx context.Context, v jsontext.Value) (location string, err error)
}

func (s *Server) formPage(ctx context.Context, spec formSpec) (FormPage, error) {
	layout, err := s.layout(ctx, spec.section)
	if err != nil {
		return FormPage{}, err
	}
	f, err := spec.handler.WithValue(spec.value).Form(ctx)
	if err != nil {
		return FormPage{}, s.publish(err)
	}
	html, err := f.WithActions(spec.action, spec.validate).HTML()
	if err != nil {
		return FormPage{}, s.publish(err)
	}
	return FormPage{Layout: layout, Title: spec.title, Form: html}, nil
}

func (s *Server) submit(ctx context.Context, spec formSpec, form url.Values) (FormResponse, error) {
	layout, err := s.layout(ctx, spec.section)
	if err != nil {
		return FormResponse{}, err
	}
	f, err := spec.handler.WithValue(spec.value).SubmitForm(ctx, form)
	if err != nil {
		return FormResponse{}, s.publish(err)
	}
	if f.Valid {
		location, err := spec.save(ctx, f.Value)
		if err == nil {
			return FormResponse{Location: location}, nil
		}
		f.Reject(s.saveError(err))
	}
	html, err := f.WithActions(spec.action, spec.validate).HTML()
	if err != nil {
		return FormResponse{}, s.publish(err)
	}
	return FormResponse{FormPage: FormPage{Layout: layout, Title: spec.title, Form: html}, status: f.StatusCode()}, nil
}

func (s *Server) validate(ctx context.Context, spec formSpec, form url.Values) (template.HTML, error) {
	f, err := spec.handler.WithValue(spec.value).Validate(ctx, form)
	if err != nil {
		return "", s.publish(err)
	}
	html, err := f.ValidationHTML()
	if err != nil {
		return "", s.publish(err)
	}
	return html, nil
}

// sqliteConstraintUnique is SQLITE_CONSTRAINT_UNIQUE.
const sqliteConstraintUnique = 2067

// saveError turns an error from saving into text that is safe to show on
// the form. A broken unique constraint is the only one a person can fix.
func (s *Server) saveError(err error) error {
	if err == nil {
		return nil
	}
	var coded interface{ Code() int }
	if errors.As(err, &coded) && coded.Code() == sqliteConstraintUnique {
		return message("That email address already belongs to another contact.")
	}
	s.log.Error("save failed", "error", err)
	return message("The change could not be saved. Try again.")
}

// message is an error worded for the person filling in the form, which
// jsonhandler shows above it.
type message string

func (m message) Error() string { return string(m) }

func idPath(prefix string, id int64) string {
	return prefix + "/" + strconv.FormatInt(id, 10)
}

func nullString(p *string) sql.NullString {
	if p == nil || *p == "" {
		return sql.NullString{}
	}
	return sql.NullString{String: *p, Valid: true}
}
